const markLeadsDelivered = `-- name: MarkLeadsDelivered :many
UPDATE leads
SET delivered_at = CURRENT_TIMESTAMP, delivered_run_id = $1
WHERE id = ANY($2::bigint[]) AND delivered_at IS NULL
RETURNING id, user_id, platform, platform_user_id, identity_kind, username, display_name, score, tier, match_reason, first_flow_id, first_task_id, last_flow_id, last_task_id, delivered_at, delivered_run_id, created_at, updated_at, contacts, note, origin, flags
`

type MarkLeadsDeliveredParams struct {
	RunID sql.NullInt64 `json:"run_id"`
	Ids   []int64       `json:"ids"`
}

func (q *Queries) MarkLeadsDelivered(ctx context.Context, arg MarkLeadsDeliveredParams) ([]Lead, error) {
	rows, err := q.db.QueryContext(ctx, markLeadsDelivered, arg.RunID, pq.Array(arg.Ids))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Lead
	for rows.Next() {
		var i Lead
		if err := rows.Scan(
			&i.ID,
			&i.UserID,
			&i.Platform,
			&i.PlatformUserID,
			&i.IdentityKind,
			&i.Username,
			&i.DisplayName,
			&i.Score,
			&i.Tier,
			&i.MatchReason,
			&i.FirstFlowID,
			&i.FirstTaskID,
			&i.LastFlowID,
			&i.LastTaskID,
			&i.DeliveredAt,
			&i.DeliveredRunID,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Contacts,
			&i.Note,
			&i.Origin,
			pq.Array(&i.Flags),
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

